16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^(\\+[0-9]{8,15}|[0-9]{10})$",
49	            message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "membership_number")
62	    private String membershipNumber;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_size")
71	    private Integer householdSize;
72	
73	    @Column(name = "membership_level")
74	    private Integer membershipLevel;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    public void setEmail(String email) {
108	        this.email = email;
109	    }
110	
111	    public LocalDate getRegistrationDate() {
112	        return this.registrationDate;
113	    }
114	
115	    public void setRegistrationDate(LocalDate registrationDate) {
116	        this.registrationDate = registrationDate;
117	    }
118	
119	    public String getCustomerCode() {
120	        return this.customerCode;
121	    }
122	
123	    public void setCustomerCode(String customerCode) {
124	        this.customerCode = customerCode;
125	    }
126	
127	    public String getMembershipNumber() {
128	        return this.membershipNumber;
129	    }
130	
131	    public void setMembershipNumber(String membershipNumber) {
132	        this.membershipNumber = membershipNumber;
133	    }
134	
135	    public String getHouseholdId() {
136	        return this.householdId;
137	    }
138	
139	    public void setHouseholdId(String householdId) {
140	        this.householdId = householdId;
141	    }
142	
143	    public Integer getNamesakeCount() {
144	        return this.namesakeCount;
145	    }
146	
147	    public void setNamesakeCount(Integer namesakeCount) {
148	        this.namesakeCount = namesakeCount;
149	    }
150	
151	    public Integer getHouseholdSize() {
152	        return this.householdSize;
153	    }
154	
155	    public void setHouseholdSize(Integer householdSize) {
156	        this.householdSize = householdSize;
157	    }
158	
159	    public Integer getMembershipLevel() {
160	        return this.membershipLevel;
161	    }
162	
163	    public void setMembershipLevel(Integer membershipLevel) {
164	        this.membershipLevel = membershipLevel;
165	    }
166	
167	    protected Set<Pet> getPetsInternal() {
168	        if (this.pets == null) {
169	            this.pets = new HashSet<>();
170	        }
171	        return this.pets;
172	    }
173	
174	    protected void setPetsInternal(Set<Pet> pets) {
175	        this.pets = pets;
176	    }
177	
178	    public List<Pet> getPets() {
179	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
180	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
181	        return Collections.unmodifiableList(sortedPets);
182	    }
183	
184	    public void setPets(List<Pet> pets) {
185	        this.pets = new HashSet<>(pets);
186	    }
187	
188	    public void addPet(Pet pet) {
189	        getPetsInternal().add(pet);
190	        pet.setOwner(this);
191	    }
192	
193	    /**
194	     * Return the Pet with the given name, or null if none found for this Owner.
195	     *
196	     * @param name to test
197	     * @return true if pet name is already in use
198	     */
199	    public Pet getPet(String name) {
200	        return getPet(name, false);
201	    }
202	
203	    /**
204	     * Return the Pet with the given name, or null if none found for this Owner.
205	     *
206	     * @param name to test
207	     * @return true if pet name is already in use
208	     */
209	    public Pet getPet(String name, boolean ignoreNew) {
210	        name = name.toLowerCase();
211	        for (Pet pet : getPetsInternal()) {
212	            if (!ignoreNew || !pet.isNew()) {
213	                String compName = pet.getName();
214	                compName = compName.toLowerCase();
215	                if (compName.equals(name)) {
216	                    return pet;
217	                }
218	            }
219	        }
220	        return null;
221	    }
222	
223	    public Pet getPet(Integer petId) {
224	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
225	    }
226	
227	    @Override
228	    public String toString() {
229	        return new ToStringCreator(this)
230	
231	            .append("id", this.getId())
232	            .append("new", this.isNew())
233	            .append("lastName", this.getLastName())
234	            .append("firstName", this.getFirstName())
235	            .append("address", this.address)
236	            .append("city", this.city)
237	            .append("telephone", this.telephone)
238	            .toString();
239	    }
240	}
