3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects creating an owner whose (already normalized) telephone is used by an existing owner.
10	 *
11	 * <p>Runs after {@link NormalizeOwnerTelephone} so the lookup compares canonical E.164 values, and
12	 * before {@link BuildOwner}/{@link SaveOwner} so a duplicate is a 409 (Conflict) rather than a
13	 * persisted row.
14	 */
15	public class EnsureOwnerTelephoneUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        if (!ownerRepository.findByTelephone(telephone).isEmpty()) {
21	            throw new DuplicateTelephoneException(telephone);
22	        }
23	    }
24	}
