11	 * <p>Runs after {@link NormalizeOwnerEmail} so the lookup compares canonical lower-cased values, and
12	 * before {@link BuildOwner}/{@link SaveOwner} so a duplicate is a 409 (Conflict) rather than a
13	 * persisted row. Email is optional: a missing (null) value is left untouched and never conflicts.
14	 */
15	public class EnsureOwnerEmailUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateEmailException {
19	        String email = request.getEmail();
20	        if (email == null) {
21	            return; // email is optional
22	        }
23	        if (!ownerRepository.findByEmail(email).isEmpty()) {
24	            throw new DuplicateEmailException(email);
