1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Rejects creating an owner who shares a household — same last name and same address — with an
13	 * existing owner, comparing both fields case-insensitively and with collapsed whitespace.
14	 *
15	 * <p>The request can opt out by setting {@code sharesHousehold} true, which acknowledges that two
16	 * owners genuinely live at the same address. Runs before {@link BuildOwner}/{@link SaveOwner} so a
17	 * clash is a 409 (Conflict) rather than a persisted row.
18	 */
19	public class EnsureOwnerHouseholdUnique {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateHouseholdException {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String lastName = normalize(request.getLastName());
27	        String address = AddressNormalizer.normalize(request.getAddress());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(normalize(existing.getLastName()))
30	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
31	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
32	            }
33	        }
34	    }
35	
36	    /** Trim, collapse internal whitespace to a single space and lower-case for comparison. */
37	    private static String normalize(String value) {
38	        if (value == null) {
39	            return "";
40	        }
41	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
42	    }
43	}
