1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.lang.reflect.Method;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.core.MethodParameter;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.validation.BeanPropertyBindingResult;
9	import org.springframework.validation.BindingResult;
10	import org.springframework.web.bind.MethodArgumentNotValidException;
11	
12	/**
13	 * Normalizes the telephone number when creating an owner into canonical E.164 form and writes it
14	 * back onto the request, so that {@link BuildOwner} persists — and the response returns — the E.164
15	 * string.
16	 *
17	 * <p>Rules: a leading {@code '+'} and country code are kept when present; otherwise country code
18	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
19	 * Spaces, dashes and brackets are stripped. The digits following the {@code '+'} must number between
20	 * 8 and 15. So {@code '0412 345 678'} becomes {@code '+61412345678'}.
21	 *
22	 * <p>When the caller supplies an explicit country code, the national-number length is additionally
23	 * validated against that country: {@code '+61'} requires 9 national digits and {@code '+1'} requires
24	 * 10. A number whose national part is the wrong length for its country is rejected as a 400.
25	 *
26	 * <p>A value that cannot form valid E.164 is rejected as a 400, mirroring the schema-validation
27	 * failures produced by {@link ValidateOwner}.
28	 */
29	public class NormalizeOwnerTelephone {
30	
31	    private static final int MIN_DIGITS = 8;
32	
33	    private static final int MAX_DIGITS = 15;
34	
35	    private static final String DEFAULT_COUNTRY_CODE = "61";
36	
37	    /**
38	     * Known country codes mapped to the exact number of national digits they require, longest code
39	     * first so {@code '61'} is matched before the shorter {@code '1'}. When an explicit country code
40	     * matches one of these, the national-number length is enforced; other codes fall back to the
41	     * generic {@link #MIN_DIGITS}..{@link #MAX_DIGITS} bound.
42	     */
43	    private static final java.util.List<CountryRule> COUNTRY_RULES = java.util.List.of(
44	            new CountryRule("61", 9), new CountryRule("1", 10));
45	
46	    private record CountryRule(String code, int nationalDigits) {
47	    }
48	
49	    private static final Method SERVICE_METHOD;
50	
51	    static {
52	        try {
53	            SERVICE_METHOD = NormalizeOwnerTelephone.class.getMethod("service", OwnerFieldsDto.class);
54	        }
55	        catch (NoSuchMethodException ex) {
56	            throw new ExceptionInInitializerError(ex);
57	        }
58	    }
59	
60	    public void service(@Val OwnerFieldsDto request) throws MethodArgumentNotValidException {
61	        String telephone = request.getTelephone();
62	        String e164 = toE164(telephone);
63	        if (e164 == null) {
64	            reject(request);
65	        }
66	        request.setTelephone(e164);
67	    }
68	
69	    /**
70	     * Convert an input telephone to E.164, or return {@code null} when it cannot form a valid one.
71	     */
72	    private static String toE164(String telephone) {
73	        String raw = telephone == null ? "" : telephone.trim();
74	        boolean hasCountryCode = raw.startsWith("+");
75	        String body = hasCountryCode ? raw.substring(1) : raw;
76	
77	        // Strip spaces, dashes and brackets; anything else remaining is invalid.
78	        String cleaned = body.replaceAll("[\\s\\-()\\[\\]]", "");
79	        if (!cleaned.matches("[0-9]+")) {
80	            return null;
81	        }
82	
83	        String digits;
84	        if (hasCountryCode) {
85	            digits = cleaned;
86	        }
87	        else {
88	            // No country code: assume +61 and drop a single leading '0' from the national digits.
89	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
90	            digits = DEFAULT_COUNTRY_CODE + national;
91	        }
92	
93	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
94	            return null;
95	        }
96	
97	        // When the caller gave an explicit country code, hold the national part to that country's
98	        // required length ('+61' => 9 digits, '+1' => 10). This is the only place we can tell the
99	        // country apart from the assumed default, so it is scoped to explicitly-coded numbers.
100	        if (hasCountryCode) {
101	            for (CountryRule rule : COUNTRY_RULES) {
102	                if (digits.startsWith(rule.code())) {
103	                    String national = digits.substring(rule.code().length());
104	                    if (national.length() != rule.nationalDigits()) {
105	                        return null;
106	                    }
107	                    break;
108	                }
109	            }
110	        }
111	        return "+" + digits;
112	    }
113	
114	    private static void reject(OwnerFieldsDto request) throws MethodArgumentNotValidException {
115	        BindingResult binding = new BeanPropertyBindingResult(request, "ownerFieldsDto");
116	        binding.rejectValue("telephone", "Telephone",
117	                "must form a valid E.164 telephone number (8 to 15 digits after the '+', "
118	                        + "and the national-number length required by the country code: +61 => 9, +1 => 10)");
119	        throw new MethodArgumentNotValidException(new MethodParameter(SERVICE_METHOD, 0), binding);
120	    }
121	}
