1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.lang.reflect.Method;
4	import java.util.Locale;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.core.MethodParameter;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.validation.BeanPropertyBindingResult;
11	import org.springframework.validation.BindingResult;
12	import org.springframework.web.bind.MethodArgumentNotValidException;
13	
14	/**
15	 * Normalizes the optional owner email. Email is optional: a missing (null) value is left untouched.
16	 * When present the value must be a syntactically valid address; it is stored — and returned — lower-cased.
17	 *
18	 * <p>A value that is present but not a valid address is rejected as a 400, mirroring the schema-validation
19	 * failures produced by {@link ValidateOwner}. Validation here is independent of the generated DTO's bean
20	 * constraints so the rule holds regardless of how the request was bound.
21	 */
22	public class NormalizeOwnerEmail {
23	
24	    /**
25	     * Pragmatic single-{@code @} address check: a non-empty local part, an {@code @}, then a domain with at
26	     * least one dot-separated label. Matches the semantics of {@code jakarta.validation.constraints.Email}
27	     * for the addresses this application accepts.
28	     */
29	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
30	
31	    private static final Method SERVICE_METHOD;
32	
33	    static {
34	        try {
35	            SERVICE_METHOD = NormalizeOwnerEmail.class.getMethod("service", OwnerFieldsDto.class);
36	        }
37	        catch (NoSuchMethodException ex) {
38	            throw new ExceptionInInitializerError(ex);
39	        }
40	    }
41	
42	    public void service(@Val OwnerFieldsDto request) throws MethodArgumentNotValidException {
43	        String email = request.getEmail();
44	        if (email == null) {
45	            return; // email is optional
46	        }
47	        if (!EMAIL.matcher(email).matches()) {
48	            BindingResult binding = new BeanPropertyBindingResult(request, "ownerFieldsDto");
49	            binding.rejectValue("email", "Email", "must be a valid email address");
50	            throw new MethodArgumentNotValidException(new MethodParameter(SERVICE_METHOD, 0), binding);
51	        }
52	        request.setEmail(email.toLowerCase(Locale.ROOT));
53	    }
54	}
