1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical form for an owner {@code address}, so that a value is stored, returned and compared in a
8	 * single consistent shape. Normalization: trim, collapse internal runs of whitespace to a single
9	 * space, upper-case, and expand common street-type abbreviations token-by-token ({@code ST} →
10	 * {@code STREET}, {@code RD} → {@code ROAD}, {@code AVE} → {@code AVENUE}).
11	 *
12	 * <p>Expansion matches only a whole space-delimited token, so {@code "st"} in {@code "12 main st"}
13	 * expands but {@code "st."} (with a trailing period) and substrings such as the {@code "st"} in
14	 * {@code "castle"} do not. A {@code null} or whitespace-only input normalizes to the empty string,
15	 * which the required-field check ({@link ValidateOwner}) treats as blank.
16	 */
17	public final class AddressNormalizer {
18	
19	    private static final Map<String, String> ABBREVIATIONS = Map.of(
20	            "ST", "STREET",
21	            "RD", "ROAD",
22	            "AVE", "AVENUE");
23	
24	    private AddressNormalizer() {
25	    }
26	
27	    /** Normalize an address to its canonical stored/compared form; {@code ""} when blank or null. */
28	    public static String normalize(String value) {
29	        if (value == null) {
30	            return "";
31	        }
32	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
33	        if (collapsed.isEmpty()) {
34	            return "";
35	        }
36	        String[] tokens = collapsed.split(" ");
37	        StringBuilder sb = new StringBuilder(collapsed.length());
38	        for (int i = 0; i < tokens.length; i++) {
39	            if (i > 0) {
40	                sb.append(' ');
41	            }
42	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
43	        }
44	        return sb.toString();
45	    }
46	}
