2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
9	 * CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first three
10	 * letters of the last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more
11	 * than the number of owners already in that city (e.g. 'SYD-SMI-0007'). Runs after
12	 * {@link BuildOwner} and before {@link SaveOwner}, so it mutates the not-yet-persisted owner in
13	 * place.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city = owner.getCity();
19	        String city3 = prefix3(city);
20	        String last3 = prefix3(owner.getLastName());
21	        int sequence = countInCity(owner, city, ownerRepository) + 1;
22	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
23	    }
24	
25	    private static String prefix3(String value) {
26	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
27	    }
28	
29	    private static int countInCity(Owner owner, String city, OwnerRepository ownerRepository) {
30	        int count = 0;
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
33	                continue;
34	            }
35	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
36	                count++;
37	            }
38	        }
39	        return count;
40	    }
41	}
